      ["#99.category"] = { { 5758972, 7 } },
      ["A BALTOY moves by spinning on its single\nfoot. It has been depicted in murals \nadorning the walls of a once-bustling city\nin an ancient age."] = { { 5749424, 123 } },
      ["A BAYLEEF's neck is ringed by curled-up\nleaves. Inside each leaf is a small tree\nshoot. The fragrance of this shoot\nmakes people peppy."] = { { 5720942, 164 } },
      ["A BEEDRILL is extremely territorial.\nFor safety reasons, no one should \never approach its nest. If angered,\nthey will attack in a swarm."] = { { 5699927, 124 } },
      ["A BELLSPROUT's thin and flexible body lets\nit bend and sway to avoid any attack,\nhowever strong it may be. From its mouth,\nit leaks a fluid that melts even iron."] = { { 5708117, 155 } },
      ["A CHARIZARD flies about in search of\nstrong opponents. It breathes intense\nflames that can melt any material. However,\nit will never torch a weaker foe."] = { { 5698544, 157 } },
      ["A CLAMPERL slams its shell closed on prey\nto prevent escape. The pearl it creates\nupon evolution is said to be infused with\na mysterious energy."] = { { 5752734, 138 } },
      ["A CLAYDOL sleeps while hovering in midair.\nIts arms are separate from its body.\nThey are kept floating by the POKéMON's\nmanipulation of psychic power."] = { { 5749548, 132 } },
      ["A CLEFABLE uses its wings to skip lightly \nas if it were flying. Its bouncy step\nlets it even walk on water. On quiet,\nmoonlit nights, it strolls on lakes."] = { { 5703076, 160 } },
      ["A DITTO rearranges its cell structure to\ntransform itself. However, if it tries to\nchange based on its memory, it will get\ndetails wrong."] = { { 5717628, 155 } },
      ["A DONPHAN is so strong it can easily haul\na dump truck. Its hide has toughened to a\nrock-hard state. An ordinary sort of\nattack won't even leave a scratch."] = { { 5733024, 147 } },
      ["A DRAGONAIR stores an enormous amount of\nenergy inside its body. It is said to alter\nthe weather around it by loosing energy\nfrom the crystals on its neck and tail."] = { { 5720151, 143 } },
      ["A DRATINI continually molts and sloughs\noff its old skin. It does so because the\nlife energy within its body steadily builds\nto reach uncontrollable levels."] = { { 5720010, 140 } },
      ["A FURRET has a very slim build. When under\nattack, it can squirm through narrow\nspaces and get away. In spite of its short\nlimbs, it is very nimble and fleet."] = { { 5722352, 161 } },
      ["A GIRAFARIG is an herbivore--it eats\ngrass and tree shoots. While it is eating,\nits tail makes chewing and swallowing\nmotions as if it were also eating."] = { { 5728633, 148 } },
      ["A GLALIE has the power to instantaneously\nfreeze moisture in the atmosphere.\nA dazzling cloud of diamondlike ice\ncrystals forms around its body."] = { { 5752136, 136 } },
      ["A GOLDUCK is an adept swimmer.\nIt sometimes joins competitive swimmers\nin training. It uses psychic powers when\nits forehead shimmers with light."] = { { 5706044, 132 } },
      ["A GOREBYSS siphons the body fluids of prey\nthrough its thin, tubular mouth. Its light\npink body color turns vivid when it\nfinishes feeding."] = { { 5753023, 156 } },
      ["A HITMONCHAN is said to possess the\nspirit of a boxer who aimed to become the\nworld champion. Having an indomitable\nspirit means that it will never give up."] = { { 5713867, 154 } },
      ["A JYNX sashays rhythmically as if it were\ndancing. Its motions are so bouncingly\nalluring, people seeing it are compelled to\nshake their hips without noticing."] = { { 5716407, 158 } },
      ["A KIRLIA has the psychic power to create \na rip in the dimensions and see into the\nfuture. It is said to dance with pleasure\non sunny mornings."] = { { 5740334, 149 } },
      ["A LARVITAR is born deep under the ground.\nIt must eat its way through the soil above\nand reach the surface for it to see its\nparents' faces."] = { { 5735125, 158 } },
      ["A MAROWAK is the evolved form of a CUBONE\nthat has grown tough by overcoming the\ngrief of losing its mother. Its tempered\nand hardened spirit is not easily broken."] = { { 5713556, 148 } },
      ["A MEW is said to possess the genes of all\nPOKéMON. It is capable of making itself\ninvisible at will, so it entirely avoids\nnotice even if it approaches people."] = { { 5720615, 161 } },
      ["A MISDREAVUS frightens people with a\ncreepy, sobbing cry. It apparently uses\nits red spheres to absorb the fear of foes\nas its nutrition."] = { { 5728147, 160 } },
      ["A MR. MIME is a master of pantomime. It can\nconvince others that something unseeable\nactually exists. Once believed, the\nimaginary object does become real."] = { { 5716093, 152 } },
      ["A NIDOKING's thick tail packs enormously\ndestructive power capable of toppling\na metal transmission tower. Once it goes\non a rampage, there is no stopping it."] = { { 5702758, 161 } },
      ["A NUMEL stores boiling magma in the hump\non its back. It is a hardy POKéMON that can\ntransport a 220-pound load. It has served\nhumans at work since long ago."] = { { 5746453, 141 } },
      ["A PARAS has parasitic tochukaso\nmushrooms growing on its back. They grow\nby drawing nutrients from the host. They\nare valued as a medicine for long life."] = { { 5704623, 161 } },
      ["A PERSIAN's six bold whiskers sense air\nmovements to determine what is in its\nvicinity. It becomes docile if grabbed\nby the whiskers."] = { { 5705732, 151 } },
      ["A PILOSWINE is covered by a thick coat\nof long hair for enduring freezing cold.\nIt uses its tusks to dig up food that has\nbeen buried under ice."] = { { 5731361, 160 } },
      ["A PINECO hangs from a tree branch and\nwaits for prey. While eating, if it is\ndisturbed by someone shaking its tree, it\nfalls on the ground and suddenly explodes."] = { { 5728782, 120 } },
      ["A POKéMON that flies endlessly in the\nozone layer. It is said it would descend\nto the ground if KYOGRE and GROUDON\nwere to fight."] = { { 5755378, 140 } },
      ["A POKéMON that has a body and wings of\nsteel. People in the past used feathers\nfallen from SKARMORY to make swords and\nknives."] = { { 5732300, 140 } },
      ["A POKéMON that has the ability to alter its\nbody colors to match its surroundings.\nA KECLEON reverts to its original colors if\nit is startled."] = { { 5750722, 119 } },
      ["A POKéMON that has wings like cottony\nclouds. After enduring winter, in which\nlittle food is available, SWABLU flocks\nmove closer to towns in the spring."] = { { 5748039, 118 } },
      ["A POKéMON that is clad in steel armor.\nA new suit of armor is made when it evolves.\nThe old, discarded armor is salvaged as\nmetal for making iron products."] = { { 5743808, 156 } },
      ["A POKéMON that is made entirely of rocks\nand boulders. If parts of its body chip off\nin battle, REGIROCK repairs itself by\nadding new rocks."] = { { 5754381, 160 } },
      ["A POKéMON that lives in the crater of\na volcano. Every 10 years, the volcanoes\non its back erupt violently. Research is\nunder way on the cause of eruption."] = { { 5746595, 154 } },
      ["A POKéMON that manipulates psychic power\nat will. It doesn't stop bouncing even when\nit is asleep. It loves eating mushrooms\nthat grow underground."] = { { 5746891, 138 } },
      ["A POKéMON that mutated from an\nextraterrestrial virus exposed to a laser\nbeam. Its body is configured for superior\nagility and speed."] = { { 5755642, 161 } },
      ["A POKéMON that sleeps 18 hours a day.\nObservation revealed that it uses\nTELEPORT to change its location once\nevery hour."] = { { 5707262, 124 } },
      ["A POKéMON that was created by genetic\nmanipulation. However, even though the\nscientific power of humans made its body,\nthey failed to give it a warm heart."] = { { 5720460, 154 } },
      ["A POKéMON that was once believed to have\nbeen extinct. The species has not changed\nits form for 100 million years. It walks on\nthe seafloor using its pectoral fins."] = { { 5753180, 154 } },
      ["A PONYTA is very weak at birth. It can\nbarely stand up. Its legs become stronger\nas it stumbles and falls while trying to\nkeep up with its parent."] = { { 5709368, 161 } },
      ["A PUPITAR creates a gas inside its body\nthat it ejects under compression to propel\nitself like a jet. Its body can withstand\na collision with solid steel."] = { { 5735284, 161 } },
      ["A QUAGSIRE hunts by leaving its mouth wide\nopen in water and waiting for its prey to\nblunder in. Because it doesn't move, it\ndoes not get very hungry."] = { { 5727369, 155 } },
      ["A QWILFISH uses the pressure of water\nit swallows to shoot toxic quills all at\nonce from all over its body. It finds\nswimming to be somewhat challenging."] = { { 5729823, 163 } },
      ["A RALTS has the power to sense the\nemotions of people and POKéMON with the\nhorns on its head. It takes cover if it\nsenses any hostility."] = { { 5740215, 118 } },
      ["A RATICATE's sturdy fangs grow steadily.\nTo keep them ground down, it gnaws on\nrocks and logs. It may even chew on the\nwalls of houses."] = { { 5700661, 155 } },
      ["A RATTATA is cautious in the extreme.\nEven while it is asleep, it constantly\nmoves its ears and listens for danger.\nIt will make its nest anywhere."] = { { 5700528, 132 } },
      ["A REMORAID uses its abdominal muscles\nto forcefully expel swallowed water, then\nshoot down flying prey. When evolution\napproaches, it travels down rivers."] = { { 5731652, 156 } },
      ["A ROSELIA that drinks nutritionally rich\nspringwater blooms with lovely flowers.\nThe fragrance of its flowers has the\neffect of making its foes careless."] = { { 5745392, 138 } },
      ["A SCIZOR has a body with the hardness of\nsteel. It is not easily fazed by ordinary\nsorts of attacks. It flaps its wings to\nregulate its body temperature."] = { { 5729987, 148 } },
      ["A SHUCKLE hides under rocks, keeping its\nbody concealed inside its shell while\neating stored berries. The berries mix with\nits body fluids to become a juice."] = { { 5730136, 146 } },
      ["A SKITTY's adorably cute behavior makes it\nhighly popular. In battle, it makes its tail\npuff out. It threatens foes with a sharp\ngrowl."] = { { 5743178, 151 } },
      ["A SMEARGLE marks its territory using a\nfluid that leaks out from the tip of its\ntail. About 5,000 different marks left by\nthis POKéMON have been found."] = { { 5733483, 162 } },
      ["A SNEASEL scales trees by punching its\nhooked claws into the bark. It seeks out\nunguarded nests and steals eggs for food\nwhile the parents are away."] = { { 5730427, 159 } },
      ["A SWELLOW dives upon prey from far above.\nIt never misses its targets. It takes to\nthe skies in search of lands with a warm\nclimate."] = { { 5739764, 138 } },
      ["A TYRANITAR is so overwhelmingly powerful,\nit can bring down a whole mountain to make\nits nest. It roams in mountains seeking\nnew opponents to fight."] = { { 5735446, 163 } },
      ["A WEEDLE has an extremely acute sense\nof smell. It distinguishes its favorite\nkinds of leaves from those it dislikes by\nsniffing with its big red proboscis (nose)."] = { { 5699605, 158 } },
      ["A WYNAUT loves to eat sweet fruits.\nIt cleverly picks fruits using its earlike\narms. They gather in fruit gardens, drawn\nby the fragrance."] = { { 5751844, 152 } },
      ["A belt is worn by a MACHOKE to keep its\noverwhelming power under control.\nBecause it is so dangerous, no one has\never removed the belt."] = { { 5707809, 154 } },
      ["A brutish POKéMON that loves to battle.\nA veteran CRAWDAUNT that has prevailed in\nhundreds of battles has giant pincers\nmarked with countless scars."] = { { 5749268, 155 } },
      ["A forest-dwelling POKéMON that is skilled\nat climbing trees. Its long and pointed\nnose is its weak point. It loses power if\nthe nose is gripped."] = { { 5739304, 144 } },
      ["A glare from its single scarlet eye makes\neven burly grown-ups freeze in utter fear.\nIt is a nocturnal POKéMON that roams\nabout under the cloak of darkness."] = { { 5751138, 158 } },
      ["A horribly noxious honey drools from its\nmouth. One whiff of the honey can result\nin memory loss. Some fans are said to\nenjoy this overwhelming stink, however."] = { { 5704295, 164 } },
      ["A nocturnal POKéMON that becomes active\nupon nightfall. It leads a VOLBEAT swarm\nto draw patterns in the night sky. Over 200\ndifferent patterns have been confirmed."] = { { 5745239, 152 } },
      ["A peculiar POKéMON species with three\nheads. It vigorously races across grassy\nplains even in arid seasons with little\nrainfall."] = { { 5710549, 115 } },
      ["A peculiar POKéMON that floats in air even\nthough its wings remain completely still.\nThe inside of its body is hollow and\nutterly dark."] = { { 5741991, 138 } },
      ["AERODACTYL is a POKéMON from the age\nof dinosaurs. It was regenerated from DNA\nextracted from amber. It is imagined to\nhave been the king of the skies."] = { { 5719224, 140 } },
      ["ARMALDO usually lives on land. However,\nwhen it hunts for prey, it dives beneath\nthe ocean. It swims around using its two\nlarge wings."] = { { 5750154, 151 } },
      ["ARTICUNO is a legendary bird POKéMON that\ncan control ice. The flapping of its wings\nchills the air. As a result, it is said that\nwhen this POKéMON flies, snow will fall."] = { { 5719520, 160 } },
      ["After many long years, its cellular\nstructure underwent a sudden mutation to\ngrow wings. When angered, it loses all\nthought and rampages out of control."] = { { 5753752, 150 } },
      ["After spending thousands of years in\nharsh deserts, its blood transformed into\nthe same substances as sand. It is\nnocturnal, so it hunts at night."] = { { 5747898, 140 } },
      ["Although it is small, it is very courageous.\nIt will take on a larger SKARMORY on an\nequal footing. However, its will weakens if\nit becomes hungry."] = { { 5739612, 151 } },
      ["Although it is small, this POKéMON is very\npowerful because its body is a bundle of\nmuscles. It launches head-butts with its\nironlike skull."] = { { 5753470, 137 } },
      ["An EEVEE has an unstable genetic makeup\nthat suddenly mutates due to its\nenvironment. Radiation from various\nSTONES causes this POKéMON to evolve."] = { { 5717784, 159 } },
      ["An EKANS curls itself up in a spiral while\nit rests. This position allows it to quickly\nrespond to an enemy from any direction\nwith a threat from its upraised head."] = { { 5701136, 157 } },
      ["An ESPEON is extremely loyal to any\nTRAINER it considers to be worthy. It is\nsaid to have developed precognitive\npowers to protect its TRAINER from harm."] = { { 5727525, 141 } },
      ["An OMASTAR uses its tentacles to capture\nits prey. It is believed to have become\nextinct because its shell grew too large,\nmaking its movements slow and ponderous."] = { { 5718741, 154 } },
      ["An abandoned plush doll became this\nPOKéMON. They are said to live in garbage\ndumps and wander about in search of the\nchildren that threw them away."] = { { 5750992, 145 } },
      ["As its energy, it uses the feelings of\ncompassion and pleasure exuded by\npeople and POKéMON. It stores up happy\nfeelings in its shell, then shares them out."] = { { 5724319, 159 } },
      ["At a meeting of POKéMON academics, it was\nannounced that simultaneous exposure to\nelectricity from a PLUSLE and MINUN will\npromote circulation and boost vitality."] = { { 5744987, 145 } },
      ["At night, a WEEPINBELL hangs on to a tree\nbranch with its hooked rear and sleeps.\nIf it moves around in its sleep, it may\nwake up to find itself on the ground."] = { { 5708273, 144 } },
      ["At night, it burrows a hole in the seafloor\nwith its broad tongue to make a place to\nsleep. While asleep, it closes its shell,\nbut leaves its tongue hanging out."] = { { 5711228, 152 } },
      ["BULBASAUR can be seen napping in bright\nsunlight. There is a seed on its back.\nBy soaking up the sun's rays, the seed\ngrows progressively larger."] = { { 5697740, 161 } },
      ["Because it darts about vigorously at high\nspeed, it is very difficult to see. Hearing\nits distinctive cries for too long induces\na headache."] = { { 5741851, 139 } },
      ["Because lightning falls in their vicinities,\nMANECTRIC were thought to have been born\nfrom lightning. In battle, they create\nthunderclouds."] = { { 5744728, 136 } },
      ["Because the triplets originally split from\none body, they think exactly alike.\nThey work cooperatively to burrow\nendlessly through the ground."] = { { 5705411, 153 } },
      ["Born from polluted sludge in the sea,\nGRIMER's favorite food is anything filthy.\nThey feed on wastewater pumped out from\nfactories."] = { { 5710944, 126 } },
      ["By baring its fangs and making a scary\nface, it sends smaller POKéMON scurrying\nin terror. The SNUBBULL does seem a\nlittle sad at making its foes flee."] = { { 5729513, 153 } },
      ["By cleverly flicking the fins on its back\nside to side, it moves in any direction\nwhile facing forward. It spits ink to\nescape if it senses danger."] = { { 5715247, 145 } },
      ["By diluting its toxic gases with a special\nprocess, the highest grade of perfume can\nbe extracted. To WEEZING, gases emanating\nfrom garbage are the ultimate feast."] = { { 5714320, 157 } },
      ["CACNEA live in deserts with virtually no\nrainfall. It battles by swinging its thick,\nspiked arms. Once a year, a yellow flower\nblooms."] = { { 5747739, 158 } },
      ["CARVANHA attack ships in swarms, making\nthem sink. Although it is said to be a very\nvicious POKéMON, it timidly flees as soon\nas it finds itself alone."] = { { 5745815, 160 } },
      ["CHANSEY lay nutritionally excellent eggs\nevery day. The eggs are so delicious, they\nare eagerly devoured by even those people\nwho have lost their appetite."] = { { 5714778, 149 } },
      ["CORSOLA live in warm southern seas.\nIf the sea becomes polluted, the beautiful\ncoral stalks become discolored and crumble\naway in tatters."] = { { 5731522, 129 } },
      ["DIGLETT are raised in most farms.\nThe reason is simple--wherever they\nburrow, the soil is left perfectly tilled\nfor growing delicious crops."] = { { 5705248, 162 } },
      ["Deep in the night, your shadow cast by\na streetlight may suddenly overtake you.\nIt is actually a GENGAR running past\nyou, pretending to be your shadow."] = { { 5711831, 160 } },
      ["Despite its small body, TOTODILE's jaws\nare very powerful. While it may think it is\njust playfully nipping, its bite has enough\nstrength to cause serious injury."] = { { 5721727, 162 } },
      ["ENTEI embodies the passion of magma.\nIt is thought to have been born in the\neruption of a volcano. It blasts fire that\nconsumes all that it touches."] = { { 5734859, 145 } },
      ["Even in hiding, it can detect the locations\nof others and sense their emotions since\nit has telepathy. Its intelligence allows\nit to understand human languages."] = { { 5754975, 148 } },
      ["Even while eating or sleeping, one of the\nheads remains always vigilant for any sign\nof danger. When threatened, it flees at\nover 60 miles per hour."] = { { 5710432, 116 } },
      ["FEEBAS live in ponds that are heavily\ninfested with weeds. Because of its\nhopelessly shabby appearance, it\nseems as if few TRAINERS raise it."] = { { 5750306, 133 } },
      ["FLAREON's fluffy fur releases heat into\nthe air so that its body does not get\nexcessively hot. Its body temperature can\nrise to a maximum of 1,650 degrees F."] = { { 5718254, 156 } },
      ["GROUDON has appeared in mythology as the\ncreator of the land. It sleeps in magma\nunderground and is said to make volcanoes\nerupt on awakening."] = { { 5755242, 135 } },
      ["Getting up close to a KOFFING will give\nyou a chance to observe, through its thin\nskin, the toxic gases swirling inside. It\nblows up at the slightest stimulation."] = { { 5714174, 145 } },
      ["HOUNDOUR communicate with each other\nusing a variety of cries to corner their\nprey. This POKéMON's remarkable teamwork\nis simply unparalleled."] = { { 5732441, 165 } },
      ["Hordes of SLAKING gather around trees\nwhen fruits come into season. They wait\naround patiently for ripened fruits to fall\nout of the trees."] = { { 5741584, 130 } },
      ["If a HAUNTER beckons you while it is\nfloating in darkness, don't approach it.\nThis POKéMON will try to lick you with its\ntongue and steal your life away."] = { { 5711675, 155 } },
      ["If a MAGBY is spouting yellow flames from\nits mouth, it is in good health. When it is\nfatigued, black smoke will be mixed in with\nthe flames."] = { { 5734262, 126 } },
      ["If attacked, it strikes back by spitting\nballs of fire it forms in its stomach.\nA TORCHIC dislikes darkness because it\ncan't see its surroundings."] = { { 5736465, 149 } },
      ["If it senses sadness with its fluffy fur,\na BLISSEY will rush over to the sad person,\nhowever far away, to share an egg of\nhappiness that brings a smile to any face."] = { { 5734553, 160 } },
      ["If it senses the approach of a storm and\na tidal wave, it protects its seaside nest\nby piling up boulders. It swims as fast as\na jet ski."] = { { 5737198, 141 } },
      ["If it stores too much electricity, its\nbehavior turns aggressive. To avoid this,\nit occasionally discharges excess energy\nand calms itself down."] = { { 5701565, 141 } },
      ["If it touches metal and discharges the\nelectricity it has stored in its body, an\nELEKID begins swinging its arms in circles\nto recharge itself."] = { { 5734105, 156 } },
      ["If you come across a young KANGASKHAN\nplaying by itself, never try to catch it.\nThe baby's parent is sure to be in the area,\nand it will become violently enraged."] = { { 5715091, 155 } },
      ["If your nose becomes itchy while you are\nsleeping, it's a sure sign that a DROWZEE is\nstanding above your pillow and trying to\neat your dream through your nostrils."] = { { 5712166, 164 } },
      ["In a HOUNDOOM pack, the one with its horns\nraked sharply back serves a leadership\nrole. They choose their leader by fighting\namong themselves."] = { { 5732607, 136 } },
      ["In battle, it blows out intense flames from\nall over its body to intimidate its foe.\nThese fiery bursts create heat waves that\nignite grass and trees in the area."] = { { 5716723, 160 } },
      ["In forests, it is said that there are many\nstreams and towering trees where an\nURSARING gathers food. It walks through\nits forest collecting food every day."] = { { 5730749, 158 } },
      ["In seasons when it produces more pollen,\nthe air around a VILEPLUME turns yellow\nwith the powder as it walks. The pollen is\nhighly toxic and causes paralysis."] = { { 5704460, 162 } },
      ["In the evening, it takes great delight in\npopping out of rivers and startling people.\nIt feeds on aquatic moss that grows on\nrocks in the riverbed."] = { { 5738827, 157 } },
      ["In the jungle, its power is without equal.\nThis POKéMON carefully grows trees and\nplants. It regulates its body temperature\nby basking in sunlight."] = { { 5736314, 150 } },
      ["In the springtime, schools of GOLDEEN\ncan be seen swimming up falls and rivers.\nIt metes out staggering damage with its\nsingle horn."] = { { 5715549, 128 } },
      ["In the wild, MIGHTYENA live in a pack.\nThey never defy their leader's orders.\nThey defeat foes with perfectly\ncoordinated teamwork."] = { { 5737490, 149 } },
      ["It actively runs about, but also falls\noften. Whenever it falls, it will check its\nreflection on a lake's surface to make\nsure its face hasn't become dirty."] = { { 5733943, 161 } },
      ["It alters its form depending on the\nweather. Changes in the climate such as\nthe temperature and humidity appear to\naffect its cellular structure."] = { { 5750581, 140 } },
      ["It apparently does not feel the pull of\ngravity because it supports itself with\npsychic power. It will give its life to\nprotect its TRAINER."] = { { 5740484, 133 } },
      ["It battles using energy it gets from\nburning coal. When loosing smoke from its\nnostrils, it lets off a sound that is\nsimilar to a locomotive's horn."] = { { 5746750, 140 } },
      ["It bears an uncanny and unexplained\nresemblance to a POKé BALL. Because it\nexplodes at the slightest shock, even\nveteran TRAINERS treat it with caution."] = { { 5712794, 135 } },
      ["It becomes very active on the night of\na full moon. This POKéMON was first\ndiscovered 40 years ago at the site of\na meteor strike."] = { { 5748609, 125 } },
      ["It blossoms when the temperature rises\nabove 64 degrees F. Because its flower's\nblooming changes with the temperature,\nit is sometimes used as a thermometer."] = { { 5726259, 158 } },
      ["It breathes through nostrils that it\nraises above the sea. By inhaling to its\nmaximum capacity, a WAILORD can dive close\nto 10,000 feet beneath the waves."] = { { 5746291, 161 } },
      ["It can circle the globe in just 16 hours.\nIt is a kindhearted POKéMON that leads\nlost and foundering ships in a storm\nto the safety of land."] = { { 5720295, 164 } },
      ["It can freely control fire, making fiery\norbs fly like will-o'-the-wisps. Just\nbefore evolution, its six tails grow hot \nas if on fire."] = { { 5703237, 155 } },
      ["It can hide behind a shimmering heat haze\nthat it creates using its intense flames.\nTYPHLOSION create blazing explosive\nblasts that burn everything to cinders."] = { { 5721575, 151 } },
      ["It can see 360 degrees without moving\nits eyes. It is a great flier capable of\nmaking sudden stops and turning midair to\nquickly chase down targeted prey."] = { { 5727062, 146 } },
      ["It can't keep still because its blood boils\nwith energy. It runs through the fields\nand mountains all day to calm itself. If it\ndoesn't, it can't sleep at night."] = { { 5741415, 168 } },
      ["It carries food bundled up in its tail.\nThere was a famous explorer who\nmanaged to scale Mt. Everest thanks\nto a DELIBIRD sharing its food."] = { { 5731977, 159 } },
      ["It catches prey by dipping its tail in\nwater at the side of a river. But it often\nforgets what it is doing and spends entire\ndays just loafing at water's edge."] = { { 5709688, 162 } },
      ["It climbs mountain paths using only the\npower of its arms. Because they look just\nlike boulders lining paths, hikers may step\non them without noticing."] = { { 5708878, 163 } },
      ["It consists of six eggs that care for each\nother. The eggs attract each other and\nspin around. When cracks increasingly\nappear, it is close to evolution."] = { { 5713086, 160 } },
      ["It continually meditates for hours every\nday. As a result of rigorous and dedicated\nyoga training, it has tempered its\nspiritual power so much it can fly."] = { { 5744298, 155 } },
      ["It continually undertakes strenuous\ntraining to master all forms of martial\narts. Its strength lets it easily hoist\na sumo wrestler onto its shoulders."] = { { 5707664, 144 } },
      ["It curls up in a ball to protect itself from\nenemy attacks. It also curls up to prevent\nheatstroke during the daytime when\ntemperatures rise sharply."] = { { 5701833, 152 } },
      ["It digs branching holes in caves using its\nsharp claws in search of food--raw gems.\nA SABLEYE lurks in darkness and is seen\nonly rarely."] = { { 5743481, 159 } },
      ["It disguises itself as seaweed by making\nits tentacles sway. Unsuspecting prey\nthat come too close are swallowed whole.\nIt became extinct 100 million years ago."] = { { 5749681, 163 } },
      ["It drags its heavy body along the\nseafloor. It makes its nest in the shallows\nof warm seas. CRADILY can be seen on\nbeaches when the tide goes out."] = { { 5749845, 144 } },
      ["It ensnares its foe with its suction-\ncupped tentacles before delivering the\nfinishing blow. If the foe turns out to be\ntoo strong, it spews ink to escape."] = { { 5731809, 167 } },
      ["It flares flames from its back to protect\nitself. The fire burns vigorously if the\nPOKéMON is angry. When it is tired,\nit sputters with incomplete combustion."] = { { 5721268, 153 } },
      ["It flies by flapping its broad leaves.\nThe bunch of fruit that grows around its\nneck is deliciously sweet. In the spring,\nit scatters pollen from its neck."] = { { 5751435, 156 } },
      ["It gathers with others in the night and\nmakes its red core glow on and off with\nthe twinkling stars. It can regenerate\nlimbs if they are severed from its body."] = { { 5715815, 142 } },
      ["It generates electricity using friction\nfrom the atmosphere. In seasons with\nespecially arid air, its entire body blazes\nwith violent showers of sparks."] = { { 5744583, 144 } },
      ["It gives off so much light that it can be\nseen even from space. People in the old\ndays used its light to send signals back\nand forth with others far away."] = { { 5725213, 158 } },
      ["It gives over five gallons of milk daily.\nIts sweet milk is enjoyed by children and\ngrown-ups alike. People who can't drink\nmilk turn it into yogurt and eat it instead."] = { { 5734389, 163 } },
      ["It glides without making a single sound.\nIt grasps the face of its foe using its\nhind and large front claws, then stabs\nwith its poison barb."] = { { 5729199, 157 } },
      ["It hangs off branches and absorbs\nnutrients. When it finishes eating, its\nbody becomes so heavy that it drops to\nthe ground with a thump."] = { { 5739150, 153 } },
      ["It hardly eats while it awaits evolution.\nIt becomes hardier by enduring hunger.\nIts shell peels off the instant it begins\nto evolve."] = { { 5753608, 143 } },
      ["It has a particularly well-developed lower\njaw. The huge fangs are heavy, causing\nit to tilt its head. Unless it is startled, it\nwill not try to bite."] = { { 5729667, 155 } },
      ["It has a superior ability to search for\ndelicious honey from flowers. It can seek,\nextract, and carry honey from flowers\nblooming over six miles away."] = { { 5699453, 151 } },
      ["It has an extremely sharp sense of\ndirection. It can unerringly return home to\nits nest, however far it may be removed\nfrom its familiar surroundings."] = { { 5700052, 165 } },
      ["It has an internal organ that senses\nthe earth's rotation. Using this special\norgan, a HOOTHOOT begins hooting at\nprecisely the same time every day."] = { { 5722514, 138 } },
      ["It has long been said that each of the\nnine tails embody an enchanted power.\nA long-lived NINETALES will have fur that\nshines like gold."] = { { 5703393, 130 } },
      ["It has sound-generating organs all over\nits body. It communicates with others by\nadjusting the tone and volume of the cries\nit emits."] = { { 5742425, 155 } },
      ["It has the enigmatic power of foreseeing\nthe future. Some people in different lands\nhave long believed that XATU are\nemissaries from another world."] = { { 5724750, 138 } },
      ["It has the habit of challenging others\nwithout hesitation to tests of strength.\nIt's been known to stand on train tracks\nand stop trains using forearm thrusts."] = { { 5742731, 164 } },
      ["It has the trait of cheering on its fellow\nPOKéMON. By shorting out the electricity\nit releases from its paws, it creates\npom-poms for cheering."] = { { 5744865, 121 } },
      ["It hums in a beautiful soprano voice.\nIt flies among white clouds in the blue\nsky. It launches intensely hot fireballs\nfrom its mouth."] = { { 5748158, 143 } },
      ["It intimidates foes with intense gusts of\nflames and superheated air. Its quick\nnimbleness lets it dodge attacks even\nwhile scorching an enemy."] = { { 5721422, 152 } },
      ["It intimidates foes with the large eyelike\npatterns on its antennae. Because it can't\nfly if its wings get wet, it shelters itself\nfrom rain under large trees and eaves."] = { { 5740772, 163 } },
      ["It is a POKéMON that has been regenerated\nfrom a fossil. However, in rare cases, living\nexamples have been discovered. KABUTO\nhave not changed for 300 million years."] = { { 5718896, 164 } },
      ["It is a nocturnal POKéMON that flies from\nfields and mountains to the attraction of\nstreetlights at night. It looses highly\ntoxic powder from its wings."] = { { 5738533, 160 } },
      ["It is a species of POKéMON that lives in\nvolcanic areas. If its body cools, its skin\nhardens and immobilizes it. To avoid that,\nit sleeps near magma."] = { { 5730908, 154 } },
      ["It is actually three MAGNEMITE linked\nby magnetism. It generates powerful radio\nwaves that raise temperatures by 3.6\ndegrees F within a 3,300-foot radius."] = { { 5710129, 147 } },
      ["It is adept at sending foes flying with\nharsh tackles using its tough, scaly body.\nThis POKéMON is at its strongest when\nit is defending its young."] = { { 5702304, 150 } },
      ["It is always seen with a stick from a plant.\nApparently, there are good sticks and bad\nsticks. This POKéMON occasionally fights\nwith others over choice sticks."] = { { 5710277, 154 } },
      ["It is an extremely vicious and violent\nPOKéMON. When humans begin to fight,\nit will appear and burn everything to the\nground with intensely hot flames."] = { { 5717328, 143 } },
      ["It is capable of reverting itself entirely\nback to program data in order to enter\ncyberspace. A PORYGON is copy-\nprotected so it cannot be duplicated."] = { { 5718411, 161 } },
      ["It is completely covered with plushy fur.\nAs a result, it never feels the cold even\nwhen it is rolling about on ice floes or\ndiving in the sea."] = { { 5752273, 136 } },
      ["It is distinguished by a pattern of\nspots that is always different. Its\nunsteady, tottering walk has the\neffect of fouling its foe's aim."] = { { 5747181, 141 } },
      ["It is exceedingly fast if it only has to run\nin a straight line. When it spots pond-\ndwelling prey underwater, it quickly leaps\nin and catches it with its sharp claws."] = { { 5737773, 163 } },
      ["It is impossible to defend against punches\nand chops doled out by its four arms.\nIts fighting spirit flares up when it faces\na tough opponent."] = { { 5707964, 152 } },
      ["It is not satisfied unless it is rampaging\nat all times. If there is no opponent for\nTAUROS to battle, it will charge at thick\ntrees and knock them down to calm itself."] = { { 5717024, 151 } },
      ["It is possible to see this POKéMON's spiral\ninnards right through its thin skin.\nHowever, the skin is also very flexible.\nEven sharp fangs bounce right off it."] = { { 5706796, 163 } },
      ["It is rumored that a boy with psychic\nabilities suddenly transformed into\nKADABRA while he was assisting research\ninto extrasensory powers."] = { { 5707387, 133 } },
      ["It is said that in lands with clean air,\nwhere the stars fill the sky, there live\nmany LEDIAN. For good reason, they use\nthe light of the stars as energy."] = { { 5722965, 155 } },
      ["It is said to arrive on chilly, wintry winds.\nFeared from long ago as the guardian of\nforests, this POKéMON lives in a deep\nforest where people do not venture."] = { { 5739449, 162 } },
      ["It is said to be a POKéMON that brings good\nfortune. When it spots someone who is pure\nof heart, a TOGETIC appears and shares its\nhappiness with that person."] = { { 5724479, 145 } },
      ["It is said to live at the bottom of\nlarge lakes. Considered to be the most\nbeautiful of all POKéMON, it has been\ndepicted in paintings and statues."] = { { 5750440, 140 } },
      ["It is said to live in volcanic craters\non mountain peaks. Once a year, it sheds\nits hide and grows larger. The shed hide\ncrumbles and returns to the soil."] = { { 5709204, 163 } },
      ["It is still inept at retaining electricity.\nWhen it is startled, it discharges power\naccidentally. It gets better at holding\npower as it grows older."] = { { 5723860, 164 } },
      ["It is thought that its body is hollow with\nonly a spectral ball of fire burning inside.\nHowever, no one has been able to\nconfirm this theory as fact."] = { { 5751297, 137 } },
      ["It keeps itself inside its steel shell.\nThe shell is opened when it is catching\nprey, but it is so quick that the shell's\ninside cannot be seen."] = { { 5728903, 151 } },
      ["It lashes out with 10 kicks per second.\nIts strong fighting instinct compels it\nto keep up its offensive until the\nopponent gives up."] = { { 5736615, 135 } },
      ["It learns martial arts that use punches\nand kicks. Every several years, its old\nfeathers burn off, and new, supple\nfeathers grow back in their place."] = { { 5736751, 150 } },
      ["It licks its palms that are sweetened by\nbeing soaked in honey. A TEDDIURSA makes\nits own honey by blending fruits and pollen\ncollected by BEEDRILL."] = { { 5730587, 161 } },
      ["It lives in complex rock formations on\nthe ocean floor and traps prey using its\n80 tentacles. Its red orbs glow when it\ngrows excited or agitated."] = { { 5708713, 164 } },
      ["It lives in water virtually all day long.\nIts body color and pattern act as\ncamouflage that makes it tough for\nenemies to spot in water."] = { { 5725635, 132 } },
      ["It looses ultrasonic waves by rubbing its\nwings together. Since a VIBRAVA's wings\nare still in the process of growing, it can\nonly fly short distances."] = { { 5747460, 138 } },
      ["It loves to eat damp, composted soil in\nforests. If you enter a forest after a\nlong rain, you can see many SHROOMISH\nfeasting on composted soil."] = { { 5740936, 157 } },
      ["It loves to snooze on bitterly cold ice.\nThe sight of this POKéMON sleeping on\na glacier was mistakenly thought to be\na mermaid by a mariner long ago."] = { { 5710815, 128 } },
      ["It loves to toughen up its body above all\nelse. If you hear quaking rumbles in a cave,\nit is the sound of MAKUHITA undertaking\nstrenuous training."] = { { 5742581, 149 } },
      ["It makes its nest at the roots of a mighty\ntree. Using its whiskerlike antennae, it\nprobes its surroundings in the\npitch-black darkness of soil."] = { { 5741715, 135 } },
      ["It makes its nest in a giant tree in the\nforest. It ferociously guards against\nanything nearing its territory. It is said\nto be the protector of the forest's trees."] = { { 5736073, 126 } },
      ["It makes its nest on a sheer cliff at the\nedge of the sea. It has trouble keeping\nits wings flapping in flight. Instead, it\nsoars on updrafts."] = { { 5739903, 150 } },
      ["It mimics a tree to avoid being attacked\nby enemies. But since its forelegs\nremain green throughout the year, it is\neasily identified as a fake in the winter."] = { { 5725768, 165 } },
      ["It opens its huge mouth to intimidate\nenemies. In battle, it runs using its thick\nand powerful hind legs to charge the\nfoe with incredible speed."] = { { 5722040, 149 } },
      ["It pines for the mother it will never see\nagain. Seeing a likeness of its mother in\nthe full moon, it cries. The stains on the\nskull it wears are from its tears."] = { { 5713410, 145 } },
      ["It positions the round speakers on its\nhead to assail foes with ultrasonic waves\nat massive volume. It builds power by\nstomping the ground."] = { { 5742267, 157 } },
      ["It prefers warm and humid habitats.\nIn the summertime, the toxic substances\nin its body intensify, making MUK reek like\nputrid kitchen garbage."] = { { 5711071, 156 } },
      ["It prepares for evolution using the\nenergy it stored while it was a WURMPLE.\nIt keeps watch over the surroundings with\nits two eyes."] = { { 5738086, 157 } },
      ["It punches holes in boulders on stream-\nbeds. This is a clever innovation that\nprevents its eggs from being attacked or\nwashed away by the current."] = { { 5715678, 136 } },
      ["It remains virtually immobile while it\nclings to a tree. However, on the inside,\nit busily prepares for evolution. This is\nevident from how hot its shell becomes."] = { { 5699764, 162 } },
      ["It roots for food by rubbing its snout\nagainst the ground. Its favorite food is a\nmushroom that grows under dried grass.\nIt occasionally roots out hot springs."] = { { 5731201, 159 } },
      ["It runs up short trees that grow on the\nsavanna to peck at new shoots.\nA NATU's eyes look as if they are\nalways observing something."] = { { 5724625, 124 } },
      ["It savagely threatens foes with bared\nfangs. It chases after fleeing targets\ntenaciously. It turns tail and runs,\nhowever, if the foe strikes back."] = { { 5737340, 149 } },
      ["It scatters spores from holes in the cap\non its head. It loves warm and humid\nclimates. It feeds on trees and plants in\nfields and forests."] = { { 5741094, 159 } },
      ["It sharply senses even subtle changes in\nthe sky and the land to predict natural\ndisasters. It is a long-lived POKéMON that\nhas a life-span of 100 years."] = { { 5751699, 144 } },
      ["It skims the tops of waves as it flies.\nWhen it spots prey, it uses its large beak\nto scoop up the victim with water.\nIt protects its eggs in its beak."] = { { 5740054, 160 } },
      ["It sleeps quietly, deep on the seafloor.\nWhen it comes up to the surface, it\ncreates a huge whirlpool that can swallow\neven ships."] = { { 5732744, 127 } },
      ["It sleeps virtually all day and night long.\nIt doesn't change its nest its entire life,\nbut it sometimes travels great distances\nby swimming in rivers."] = { { 5741254, 160 } },
      ["It sticks to tree branches and eats\nleaves. The thread it spits from its mouth,\nwhich becomes gooey when it touches\nair, slows the movement of its foes."] = { { 5737937, 148 } },
      ["It stores electricity in the electric sacs\non its cheeks. When it releases pent-up\nenergy in a burst, the electric power is\nequal to a lightning bolt."] = { { 5701436, 128 } },
      ["It stores power in the black pearls on its\nforehead. When it uses psychic power, it\nperforms an odd dance step. Its style of\ndancing became hugely popular overseas."] = { { 5747030, 150 } },
      ["It swims in the sea by swallowing water,\nthen jetting it out toward the rear.\nThe CLOYSTER shoots spikes from its\nshell using the same system."] = { { 5711381, 147 } },
      ["It undertakes research every day to\nsolve the mysteries of the world.\nHowever, it apparently forgets everything\nif the SHELLDER on its head comes off."] = { { 5727985, 161 } },
      ["It unfailingly catches prey in darkness.\nNOCTOWL owe their success to superior\nvision that allows them to see in minimal\nlight, and to their supple and silent wings."] = { { 5722653, 154 } },
      ["It usually canters casually in the fields\nand plains. But once a RAPIDASH turns\nserious, its fiery manes flare and blaze\nas it gallops its way up to 150 mph."] = { { 5709530, 157 } },
      ["It was created by humans using the power\nof science. It has been given artificial\nintelligence that enables it to learn new\ngestures and emotions on its own."] = { { 5733172, 157 } },
      ["It was resurrected from a fossil using the\npower of science. It swims by undulating\nthe eight wings at its sides. They were\nfeet that adapted to life in the sea."] = { { 5749990, 163 } },
      ["It waves its huge, oversized claw in the\nair to communicate with others.\nBut since the claw is so heavy, this\nPOKéMON quickly tires."] = { { 5712642, 151 } },
      ["It waves its leaf around to keep foes\nat bay. However, a sweet fragrance also\nwafts from the leaf, creating a friendly\natmosphere that becalms the battlers."] = { { 5720777, 164 } },
      ["Its big jaws crunch through boulders.\nBecause its head is so big, it has a hard\ntime getting back upright if it tips over\nonto its back."] = { { 5747323, 136 } },
      ["Its blindingly fast speed adds to the\nsharpness of its twin forearm scythes.\nThe scythes can slice through thick logs\nin one wicked stroke."] = { { 5716246, 160 } },
      ["Its body emits a powerful magnetism.\nIt feeds on prey that is pulled in by the\nforce. Its magnetism is stronger in cold\nseasons."] = { { 5743043, 134 } },
      ["Its body is almost entirely composed of\nwater. It ensnares its foe with its two\nlong tentacles, then stabs with the poison\nstingers at their tips."] = { { 5708572, 140 } },
      ["Its body is covered with a slimy film.\nThe film acts as a barrier to prevent germs\nin muddy water from entering the\nBARBOACH's body."] = { { 5748854, 129 } },
      ["Its body is covered with water-repellent\nfur. Because of the fur, it can swim\nthrough water at high speed without being\nslowed by the water's resistance."] = { { 5725512, 122 } },
      ["Its body is harder than any other kind of\nmetal. The body metal is composed of a\nmysterious substance. Not only is it hard,\nit shrinks and stretches flexibly."] = { { 5754665, 166 } },
      ["Its body surface is always wet and slick\nwith an oily fluid. Because of this greasy\ncovering, it can easily slip and slide out\nof the clutches of any enemy in battle."] = { { 5706960, 135 } },
      ["Its cells generate weak power that is\namplified by its fur's static electricity\nto drop thunderbolts. The bristling fur is\nmade of electrically charged needles."] = { { 5718104, 149 } },
      ["Its coat of thin, stiff hair that covers\nits entire body is said to have evolved\nfor protection. Its large eyes never fail\nto spot even miniscule prey."] = { { 5704941, 155 } },
      ["Its colorfully patterned wings are its\nmost prominent feature. It flies through\nflower-covered fields collecting pollen.\nIt attacks ferociously when angered."] = { { 5738244, 144 } },
      ["Its cries equal a jet plane in volume.\nIt inhales through its ear canals. Because\nof this system, it can cry continually\nwithout having to catch its breath."] = { { 5742130, 136 } },
      ["Its drill-tipped tail is used to burrow into\nthe ground backwards. This POKéMON is\nknown to make its nest in complex shapes\ndeep under the ground."] = { { 5729055, 143 } },
      ["Its entire body is made of Antarctic ice.\nAfter extensive studies, researchers\nbelieve the ice was formed during an\nice age."] = { { 5754542, 122 } },
      ["Its fangs easily puncture even thick\nanimal hide. It loves to feast on the blood\nof people and POKéMON. It flits about in\ndarkness and strikes from behind."] = { { 5703996, 156 } },
      ["Its feathers--which glow in seven colors\ndepending on the angle at which they are\nstruck by light--are thought to bring joy.\nIt is said to live at the foot of a rainbow."] = { { 5735773, 143 } },
      ["Its feet are tipped with tiny hooked claws\nthat enable it to scuttle on ceilings and\nvertical walls. It constricts its foe with\nthin and strong silk webbing."] = { { 5723284, 158 } },
      ["Its fleece quality changes to generate\nstrong static electricity with a small\namount of wool. The bare, slick parts of its\nhide are shielded against electricity."] = { { 5725049, 163 } },
      ["Its flower petals deepen in color through\nexposure to sunlight. When cloudy weather\npersists, it does a dance that is thought\nto be a ritual for summoning the sun."] = { { 5725372, 139 } },
      ["Its fluffy wool rubs together and builds\na static charge. The more energy is\ncharged, the more brightly the lightbulb\nat the tip of its tail glows."] = { { 5724889, 159 } },
      ["Its fur is the ultimate in luxuriousness.\nSleeping alongside a WIGGLYTUFF is simply\ndivine. Its body expands seemingly without\nend when it inhales."] = { { 5703676, 155 } },
      ["Its giant jaws are actually steel horns\nthat transformed. It fools foes into\ncomplacency with its adorable gestures,\nthen chomps them with its huge jaws."] = { { 5743641, 166 } },
      ["Its highly developed muscles never grow\nfatigued, however much it exercises.\nThis POKéMON can swim back and forth\nacross the Pacific Ocean without effort."] = { { 5707096, 165 } },
      ["Its highly toxic barbs are thought to have\ndeveloped as protection for this small-\nbodied POKéMON. When enraged, it releases\na horrible toxin from its horn."] = { { 5701986, 153 } },
      ["Its horn is harder than a diamond.\nIf it senses a hostile presence, all the\nbarbs on its back bristle up at once, and it\nchallenges the foe with all its might."] = { { 5702598, 159 } },
      ["Its horn, which rotates like a drill,\ndestroys tall buildings with one strike.\nIt stands on its hind legs, and its brain\nis well developed."] = { { 5714613, 164 } },
      ["Its iron horns grow longer a little at\na time. They are used to determine the\nAGGRON's age. The gouges in its armor are\nworn with pride as mementos from battles."] = { { 5744133, 164 } },
      ["Its large tail is covered with rich, thick\nfur that deepens in color with age.\nThe scratches on its shell are evidence\nof this POKéMON's toughness in battle."] = { { 5698863, 151 } },
      ["Its legs freely stretch and contract.\nUsing these springlike limbs, it bowls over\nfoes with devastating kicks. After battle,\nit rubs down its tired legs."] = { { 5713705, 161 } },
      ["Its long neck and elongated beak are\nideal for catching prey in soil or water.\nIt deftly moves this extended and skinny\nbeak to pluck prey."] = { { 5700966, 169 } },
      ["Its loud cry can be heard over half a mile\naway. If its high, keening cry is heard\nechoing all around, it is a sign that they\nare warning each other of danger."] = { { 5700817, 148 } },
      ["Its powerful stomach acid is capable of\ndigesting almost anything. The one thing\nin the whole world a SWALOT can't digest is\nits own stomach."] = { { 5745680, 134 } },
      ["Its shell is as hard as an iron slab.\nA METAPOD does not move very much\nbecause it is preparing its soft innards\nfor evolution inside the shell."] = { { 5699296, 156 } },
      ["Its shell is not just for protection.\nIts rounded shape and the grooves on its\nsurface minimize resistance in water,\nenabling SQUIRTLE to swim at high speeds."] = { { 5698702, 160 } },
      ["Its soft and pliable body is very bouncy.\nWhen it sings continuously with all its\nmight, its body steadily turns a deepening\npink color."] = { { 5724181, 137 } },
      ["Its superb sense of smell ensures that\nthis POKéMON won't forget any scent,\nno matter what. It uses its sense of smell\nto detect the emotions of others."] = { { 5706497, 147 } },
      ["Its swimming muscles are weak, so it is\neasily washed away by currents. In places\nwhere water pools, you can see many\nMAGIKARP deposited there by the flow."] = { { 5717176, 151 } },
      ["Its tail ends with a dexterous, handlike\nappendage. However, because it uses the\ntail so much, AIPOM's real hands have\nbecome rather clumsy."] = { { 5726583, 159 } },
      ["Its tail has a SHELLDER firmly attached\nwith a bite. As a result, the tail can't be\nused for fishing anymore. This forces it\nto reluctantly swim and catch prey."] = { { 5709851, 149 } },
      ["Its tail, which is packed with nutrition,\nis very bouncy like a rubber ball. On sunny\ndays they gather at the edge of water and\nsplash about for fun."] = { { 5742896, 146 } },
      ["Its technique of kicking while spinning is\na remarkable mix of both offense and\ndefense. HITMONTOP travel faster\nspinning than they do walking."] = { { 5733784, 158 } },
      ["Its toughened hind legs enable it to stand\nupright. Because it weakens if its skin\ndries out, it replenishes fluids by playing\nin mud."] = { { 5737045, 152 } },
      ["Its vines snap off easily and painlessly\nif they are grabbed, allowing it to make a\nquick getaway. The lost vines are replaced\nby new growth the very next day."] = { { 5714928, 162 } },
      ["Its voracious appetite compels it to\ndevour leaves bigger than itself without\nhesitation. It releases a terribly strong\nodor from its antennae."] = { { 5699153, 142 } },
      ["JIRACHI is said to make wishes come true.\nWhile it sleeps, a tough crystalline shell\nenvelops the body to protect it from\nenemies."] = { { 5755519, 122 } },
      ["JUMPLUFF ride warm southern winds to\ncross the sea and fly to foreign lands.\nThis POKéMON lands when it encounters\ncold air while it is floating."] = { { 5726418, 164 } },
      ["KABUTOPS once swam underwater to hunt \nfor prey. It was apparently evolving from\nbeing a water dweller to living on land as\nevident from changes in its gills and legs."] = { { 5719061, 162 } },
      ["KRABBY live in holes dug into beaches.\nOn sandy shores with little in the way\nof food, they can be seen squabbling with\neach other over territory."] = { { 5712491, 150 } },
      ["KYOGRE has appeared in mythology as the\ncreator of the sea. After long years of\nfeuding with GROUDON, it took to sleep at\nthe bottom of the sea."] = { { 5755124, 117 } },
      ["LEDYBA communicate using a fluid that\nthey secrete from where the legs join the\nbody. They are said to convey feelings to\nothers by altering the fluid's scent."] = { { 5722808, 156 } },
      ["LUGIA is so powerful even a light\nfluttering of its wings can blow apart\nhouses. As a result, it chooses to live out\nof sight deep under the sea."] = { { 5735610, 162 } },
      ["LUVDISC make the branches of CORSOLA\ntheir nests. There is a custom from long\nago of giving a LUVDISC as a gift to\nexpress one's feelings of love."] = { { 5753335, 134 } },
      ["Leaves grow out of this POKéMON's body.\nThey help obscure a GROVYLE from the eyes\nof its enemies while it is in a thickly\novergrown forest."] = { { 5736200, 113 } },
      ["MEOWTH withdraw their sharp claws into\ntheir paws to silently sneak about.\nFor some reason, this POKéMON loves\nshiny coins that glitter with light."] = { { 5705565, 166 } },
      ["METAGROSS has four brains that are joined\nby a complex neural network. As a result of\nintegration, this POKéMON is smarter than\na supercomputer."] = { { 5754216, 164 } },
      ["MOLTRES is a legendary bird POKéMON\nthat can control fire. If injured, it is said\nto dip its body in the molten magma of\na volcano to burn and heal itself."] = { { 5719839, 170 } },
      ["MURKROW were feared as the alleged\nbearers of ill fortune. It shows strong\ninterest in anything that sparkles. It will\neven try to steal rings from women."] = { { 5727816, 168 } },
      ["Mysteriously, it can foretell earthquakes.\nIn the daytime, it sleeps in mud at the\nbottom of a pond. When it awakens, it\ncontinually feeds throughout the night."] = { { 5748984, 136 } },
      ["Nothing can avoid falling asleep hearing a\nJIGGLYPUFF's song. The sound waves of its\nsinging voice match the brain waves of\nsomeone in a deep sleep."] = { { 5703524, 151 } },
      ["On every night of a full moon, they come\nout to play. When dawn arrives, the tired\nCLEFAIRY go to sleep nestled up against\neach other in deep and quiet mountains."] = { { 5702920, 155 } },
      ["On land, it can powerfully lift large\nboulders by planting its four feet and\nheaving. It sleeps by burying itself in soil\nat the water's edge."] = { { 5736902, 142 } },
      ["On nights with many shooting stars,\nCLEFFA can be seen dancing in a ring.\nThey dance until daybreak, when they\nquench their thirst with the morning dew."] = { { 5724025, 155 } },
      ["On sunny days, schools of MANTINE can be\nseen elegantly leaping over the waves.\nIt is not bothered by the REMORAID that\nhitches rides."] = { { 5732137, 162 } },
      ["Once it grips prey with its large pincers,\nit will never let go, no matter what.\nIt is a hardy POKéMON that can thrive\nin any environment."] = { { 5749121, 146 } },
      ["Once it starts running, it doesn't stop.\nIts tiny brain makes it so stupid that it\ncan't remember why it started running in\nthe first place."] = { { 5714478, 134 } },
      ["Once its jaws clamp down on its foe, it will\nabsolutely not let go. Because the tips of\nits fangs are forked back like fishhooks,\nthey become irremovably embedded."] = { { 5721890, 149 } },
      ["One of the ancient and long-since-extinct\nPOKéMON that have been regenerated\nfrom fossils by humans. If attacked,\nit withdraws into its hard shell."] = { { 5718573, 167 } },
      ["Originally from the tropics, EXEGGUTOR's\nheads grow larger from exposure to strong\nsunlight. It is said that when the heads\nfall, they group to form an EXEGGCUTE."] = { { 5713247, 162 } },
      ["Over the course of evolution, its hind legs\nturned into wings. By alternately resting\nits front and rear wings, it can fly all day\nwithout having to stop."] = { { 5723443, 148 } },
      ["PARASECT are known to infest the roots of\nlarge trees en masse and drain nutrients.\nWhen an infested tree dies, they move\nonto another tree all at once."] = { { 5704785, 155 } },
      ["PHANPY's big ears serve as broad fans.\nWhen it becomes hot, it flaps the ears\nbusily to cool down. Even the young are\nvery strong."] = { { 5732872, 151 } },
      ["People have driven LAPRAS almost to the\npoint of extinction. In the evenings,\nit is said to sing plaintively as it seeks\nwhat few others of its kind still remain."] = { { 5717472, 155 } },
      ["People in ancient times imagined that\nSTARMIE were transformed from the\nreflections of stars that twinkled on\ngentle waves at night."] = { { 5715958, 134 } },
      ["RAIKOU embodies the speed of lightning.\nIts roars send shock waves shuddering\nthrough the air and ground as if\nlightning bolts were crashing down."] = { { 5734714, 144 } },
      ["Rather than keeping a permanent lair,\nit habitually seeks comfortable spots and\nsleeps there. It is nocturnal and becomes\nactive at dusk."] = { { 5743330, 150 } },
      ["Rubbing its nose against the ground, it\nalways wanders about back and forth in\nsearch of something. It is distinguished\nby the zigzag footprints it leaves."] = { { 5737640, 132 } },
      ["SEALEO live in herds on ice floes. Using its\npowerful flippers, it shatters ice.\nIt dives into the sea to hunt prey five\ntimes a day."] = { { 5752410, 157 } },
      ["SEEL hunt for prey in frigid, ice-covered\nseas. When it needs to breathe, it punches\na hole through the ice with the sharply\nprotruding section of its head."] = { { 5710665, 149 } },
      ["SEVIPER and ZANGOOSE are eternal rivals.\nIt counters a ZANGOOSE's dazzling agility\nwith its swordlike tail, which also oozes\na horrible poison."] = { { 5748457, 151 } },
      ["SNORLAX's typical day consists of nothing\nmore than eating and sleeping. It is such\na docile POKéMON that there are children\nwho use its big belly as a place to play."] = { { 5719365, 154 } },
      ["STANTLER's magnificent antlers were\nonce traded at high prices as works of art.\nAs a result, this POKéMON was hunted\nclose to extinction."] = { { 5733330, 152 } },
      ["STEELIX live even further underground\nthan ONIX. This POKéMON is known to dig\ntoward the earth's core, reaching a depth\nof over six-tenths of a mile underground."] = { { 5729357, 155 } },
      ["SUICUNE embodies the compassion of\na pure spring of water. It runs across\nthe land with gliding elegance. It has the\npower to purify dirty water."] = { { 5735005, 119 } },
      ["SUNFLORA convert solar energy into\nnutrition. They are highly active in the\nwarm daytime but suddenly stop moving as\nsoon as the sun sets."] = { { 5726901, 160 } },
      ["SUNKERN try to minimize movement to\nconserve the nutrients they have stored\nin their bodies for evolution. They will\nnot eat, subsisting only on morning dew."] = { { 5726743, 157 } },
      ["Solar energy is the source of this \nPOKéMON's power. On sunny days, groups of\nSOLROCK line up facing the sun and absorb\nits light."] = { { 5748735, 118 } },
      ["TYROGUE become stressed out if they do\nnot get to train every day. When raising\nthis POKéMON, the TRAINER must establish\na regular training schedule."] = { { 5733646, 137 } },
      ["The arcing movement and glitter of the\npendulum in a HYPNO's hand lull the foe\ninto deep hypnosis. While searching for\nprey, it polishes the pendulum."] = { { 5712331, 159 } },
      ["The claws tipping its arms pack the\ndestructive power to tear through thick\niron sheets as if they were silk. It flies\nat over 60 miles per hour."] = { { 5754061, 154 } },
      ["The curled hair on its head proves its\nstatus as a king. It is said that the\nlonger and curlier the hair, the more\nrespect it earns from its peers."] = { { 5725934, 161 } },
      ["The flame that burns at the tip of its\ntail is an indication of its emotions.\nThe flame wavers when CHARMANDER is\nhappy, and blazes when it is enraged."] = { { 5698219, 164 } },
      ["The flapping of its wings sounds like\nsinging. To prevent detection by enemies,\nit hides itself by flapping up a cloud of\ndesert sand."] = { { 5747599, 139 } },
      ["The fragrance of a MEGANIUM's flower\nsoothes and calms emotions. In battle,\nit gives off more of its becalming scent\nto blunt the foe's fighting spirit."] = { { 5721107, 160 } },
      ["The light-emitting orbs on its back are\nvery bright. They are formed from a part of\nits dorsal fin. This POKéMON illuminates\nthe inky darkness of deep seas."] = { { 5723730, 129 } },
      ["The long vine extending from its head is\nwaved about as if it were a living thing to\nattract prey. When an unsuspecting victim\napproaches, it is swallowed whole."] = { { 5708418, 153 } },
      ["The male NIDORAN has developed muscles\nthat freely move its ears in any direction.\nEven the slightest sound does not escape\nthis POKéMON's notice."] = { { 5702455, 142 } },
      ["The poisonous barbs all over its body are\nhighly valued as ingredients for making\ntraditional herbal medicine. It shows no\nmercy to anything approaching its nest."] = { { 5715393, 155 } },
      ["The shell on its back is made of hardened\nmagma. Tens of thousands of years spent\nliving in volcanic craters have turned\nMAGCARGO's bodies into magma."] = { { 5731063, 137 } },
      ["The units at its sides are extremely\npowerful magnets. They generate enough\nmagnetism to draw in iron objects from\nover 300 feet away."] = { { 5710001, 127 } },
      ["The vicious and sly gangster of the sea.\nIts skin is specially textured to minimize\ndrag in water. Its speed tops out at over\n75 miles per hour."] = { { 5745976, 153 } },
      ["The waterspouts that protrude from its\nshell are highly accurate. Their bullets of\nwater can precisely nail tin cans from\na distance of over 160 feet."] = { { 5699015, 137 } },
      ["The web it spins can be considered its\nsecond nervous system. It is said that a\nSPINARAK determines its prey by the tiny\nvibrations it feels through the web."] = { { 5723121, 162 } },
      ["Their pincers are strong enough to\nshatter thick logs. Because they dislike\ncold, PINSIR burrow and sleep under\nthe ground on chilly nights."] = { { 5716884, 139 } },
      ["There is a magnet in its brain that\nprevents an ONIX from losing direction\nwhile tunneling. As it grows older, its body\nbecomes steadily rounder and smoother."] = { { 5711992, 173 } },
      ["They appear in great numbers at electric\npower plants. Because they feed on\nelectricity, they cause massive and\nchaotic blackouts in nearby cities."] = { { 5712930, 155 } },
      ["They descend from mountains by tumbling\ndown steep slopes. They are so brutal,\nthey smash aside obstructing trees and\nmassive boulders with thunderous tackles."] = { { 5709042, 161 } },
      ["They fly about very actively when the hot\nseason arrives. They communicate among\nthemselves using seven different and\ndistinguishing cries."] = { { 5751592, 106 } },
      ["They gather in forests seeking the sweet\nsap of trees. It is completely clad in a\nsteel-hard shell. It is proud of its horn,\nwhich it uses to fling foes."] = { { 5730283, 143 } },
      ["They gather on puddles after evening\ndownpours, gliding across the surface\nof water as if sliding. It secretes honey\nwith a sweet aroma from its head."] = { { 5740618, 153 } },
      ["They make a small herd of only several\nmembers. They rarely make contact with\npeople or other POKéMON. They disappear\nif they sense enemies."] = { { 5754832, 142 } },
      ["They take turns standing guard when it\nis time to sleep. The sentry awakens the\nothers if it senses danger. If one becomes\nseparated, it turns sleepless with fear."] = { { 5722190, 161 } },
      ["They tend to move about in groups of\naround five SNORUNT. In snowy regions,\nit is said that when they are seen late at\nnight, snowfall will arrive by morning."] = { { 5751997, 138 } },
      ["This POKéMON came from the future by\ncrossing over time. It is thought that so\nlong as CELEBI appears, a bright and\nshining future awaits us."] = { { 5735917, 155 } },
      ["This POKéMON drifts and floats with the\nwind. If it senses the approach of strong\nwinds, a HOPPIP links leaves with others\nto prepare against being blown away."] = { { 5726096, 162 } },
      ["This POKéMON flies around, patrolling its\nlarge territory. If its living space is\nviolated, it shows no mercy in thoroughly\npunishing the foe with its sharp claws."] = { { 5700218, 148 } },
      ["This POKéMON grows by absorbing moonlight.\nDuring the daytime, it buries itself in the\nground, leaving only its leaves exposed to\navoid detection by its enemies."] = { { 5704153, 141 } },
      ["This POKéMON has a terrifically strong\nconstricting power. It can even flatten\nsteel oil drums. Once it wraps its body\naround its foe, escaping is impossible."] = { { 5701294, 141 } },
      ["This POKéMON has gorgeous, glossy\nfeathers. Many TRAINERS are so captivated\nby the beautiful feathers on its head that\nthey choose PIDGEOT as their POKéMON."] = { { 5700367, 160 } },
      ["This POKéMON is shaped like ancient text\ncharacters. Although research is ongoing,\nit is a mystery as to which came first,\nthe ancient writings or the various UNOWN."] = { { 5728308, 159 } },
      ["This POKéMON lives in ponds with clean\nwater. It is known to ferry small POKéMON\nacross ponds by carrying them on the\nbroad leaf on its head."] = { { 5738694, 132 } },
      ["This POKéMON roams about deep in the\nnight seeking such negative emotions as\ngrudges and envy. It retreats to its nest\nwhen the sun begins to rise."] = { { 5750842, 149 } },
      ["This POKéMON's stomach fluid can even\ndigest scrap iron. In one gulp, it can\nswallow something that is as large as\nitself."] = { { 5745531, 148 } },
      ["This fleet-footed POKéMON is said to run\nover 6,200 miles in a single day and night.\nThe fire that blazes wildly within its body\nis its source of power."] = { { 5706645, 150 } },
      ["This is a newly discovered POKéMON.\nIt is currently under investigation.\nNo detailed information is available\nat this time."] = { { 5697597, 142 } },
      ["Through crushingly harsh yoga training, it\ngained the power to foretell its foe's\nactions. It battles with elegant, dance-\nlike movement."] = { { 5744454, 128 } },
      ["To avoid detection by its enemies, it hides\nmotionlessly beneath large leaves and in\nthe gaps of branches. It also attaches\ndead leaves to its body for camouflage."] = { { 5738389, 143 } },
      ["To protect its herd, the leader battles\nanything that invades its territory, even\nat the cost of its life. Its tusks may snap\noff in battle."] = { { 5752568, 165 } },
      ["To support its bulb, IVYSAUR's legs\ngrow sturdy. If it spends more time lying in\nthe sunlight, the bud will soon bloom into\na large flower."] = { { 5697902, 148 } },
      ["To withstand the crushing pressure of\nwater deep under the sea, its spine is very\nthick and sturdy. Its tail, which is shaped\nlike a small fish, has eyes that light up."] = { { 5752873, 149 } },
      ["UMBREON evolved from exposure to the\nmoon's energy pulses. It lurks in darkness\nand waits for its foes to move. The rings\non its body glow when it leaps to attack."] = { { 5727667, 148 } },
      ["Usually docile, a WOBBUFFET strikes back\nferociously if its black tail is attacked.\nIt makes its lair in caves where it waits\nfor nightfall."] = { { 5728468, 164 } },
      ["VAPOREON underwent a spontaneous\nmutation and grew fins and gills that\nallow them to live underwater. They have\nthe ability to freely control water."] = { { 5717944, 159 } },
      ["VENOMOTH are nocturnal--they only are\nactive at night. Their favorite prey are\ninsects that gather around streetlights,\nattracted by the light in the darkness."] = { { 5705097, 150 } },
      ["VENUSAUR's flower is said to take on vivid\ncolors if it gets plenty of nutrition and\nsunlight. The flower's aroma soothes the\nemotions of people."] = { { 5698051, 167 } },
      ["WOOPER usually live in water but come\nout onto land seeking food occasionally.\nOn land, they coat their bodies with a\ngooey, toxic film."] = { { 5727209, 159 } },
      ["When BELDUM gather in a swarm, they move\nin perfect unison as if they were but one\nPOKéMON. They communicate with each other\nusing brain waves."] = { { 5753903, 157 } },
      ["When a storm approaches, it competes with\nothers to scale heights that are likely to\nbe stricken by lightning. Some towns use\nELECTABUZZ in place of lightning rods."] = { { 5716566, 156 } },
      ["When exposed to a strong wind, a GASTLY's\ngaseous body quickly dwindles away.\nThey cluster under the eaves of houses\nto escape the ravages of wind."] = { { 5711529, 145 } },
      ["When it battles, it stands on its hind legs\nand attacks with its sharply clawed\nforelegs. Its fur bristles if it encounters\nany SEVIPER."] = { { 5748302, 154 } },
      ["When it becomes furious, its blood\ncirculation becomes more robust, and\nits muscles are made stronger. But it\nalso becomes much less intelligent."] = { { 5706335, 161 } },
      ["When it curls up in a ball, it can make any\nattack bounce off harmlessly. Its hide has\nturned tough and solid as a result of\nliving in the desert."] = { { 5701707, 125 } },
      ["When it hears festive music, all the cells\nin its body become stimulated, and it\nbegins moving in rhythm. It does not\nquail even when it faces a tough opponent."] = { { 5738985, 164 } },
      ["When it is with its friends or\nfamily, its barbs are tucked away to\nprevent injury. It appears to become\nnervous if separated from the others."] = { { 5702140, 163 } },
      ["When it senses danger, it discharges\npositive and negative electricity from its\ntwo antennae. It lives in depths beyond\nsunlight's reach."] = { { 5723592, 137 } },
      ["When it starts shaking and its nasal\nbreathing turns rough, it's a sure sign\nof anger. However, since this happens\ninstantly, there is no time to flee."] = { { 5706177, 157 } },
      ["When its headache intensifies, it starts\nusing strange powers. However, it has no\nrecollection of its powers, so it always\nlooks befuddled and bewildered."] = { { 5705884, 159 } },
      ["When two LAIRON meet in the wild, they\nfight for territory by bashing into each\nother with their steel bodies. The sound\nof their collision carries for miles."] = { { 5743965, 167 } },
      ["Whenever it sees something unfamiliar,\nit always licks the object because it\nmemorizes things by texture and taste.\nIt is somewhat put off by sour things."] = { { 5714022, 151 } },
      ["While it has strong psychic abilities and\nhigh intelligence, an ALAKAZAM's muscles\nare very weak. It uses psychic power to\nmove its body."] = { { 5707521, 142 } },
      ["While living in pitch-black caverns, their\neyes gradually grew shut and deprived\nthem of vision. They use ultrasonic waves\nto detect obstacles."] = { { 5703832, 163 } },
      ["While this POKéMON usually lives in the sea,\nit can survive on land, although not too\nlong. It loses vitality if its body becomes\ndried out."] = { { 5746130, 160 } },
      ["With their taillights lit, VOLBEAT fly in\na swarm, drawing geometric designs in the\nnight sky. They move their nests if their\npond water becomes dirty."] = { { 5745133, 105 } },
      ["Without pity, its sharp claws destroy foes.\nIf it encounters a strong enemy, it\nbecomes agitated, and the flame on its\ntail flares with a bluish white color."] = { { 5698384, 159 } },
      ["ZAPDOS is a legendary bird POKéMON that\nhas the ability to control electricity.\nIt usually lives in thunderclouds. It gains\npower if it is stricken by lightning bolts."] = { { 5719681, 157 } },
    },
